result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "intpack.py", "content": """"Delta+varint compression for sorted integer lists.

Format:
    [count:LEB128] [first_value:LEB128] [delta_1:LEB128] ... [delta_{n-1}:LEB128]

All integers are encoded as unsigned LEB128 varints. Deltas between
consecutive values must be strictly positive; the input list must be
strictly increasing. Violations raise InputError.
"""

from __future__ import annotations

from typing import Iterator, List


class InputError(ValueError):
    """Raised for unsorted input or equal neighboring values."""


def _encode_varint(value: int) -> bytes:
    """Encode a non-negative integer as an unsigned LEB128 varint."""
    if value < 0:
        raise InputError(f"cannot encode negative value: {value}")
    out = bytearray()
    while True:
        byte = value & 0x7F
        value >>= 7
        if value:
            out.append(byte | 0x80)
        else:
            out.append(byte)
            return bytes(out)


def _decode_varint(data: bytes, pos: int) -> tuple[int, int]:
    """Decode one unsigned LEB128 varint at ``pos``. Returns (value, new_pos)."""
    result = 0
    shift = 0
    while True:
        if pos >= len(data):
            raise InputError("truncated varint")
        byte = data[pos]
        pos += 1
        result |= (byte & 0x7F) << shift
        if not (byte & 0x80):
            return result, pos
        shift += 7
        if shift > 70:  # 2**48 fits easily; guard against runaway input
            raise InputError("varint too long")


def _validate(sorted_ints: List[int]) -> None:
    prev = None
    for v in sorted_ints:
        if v < 0:
            raise InputError(f"negative value not supported: {v}")
        if prev is not None:
            if v < prev:
                raise InputError(f"unsorted input: {prev} > {v}")
            if v == prev:
                raise InputError(f"duplicate neighbor value: {v}")
        prev = v


def pack(sorted_ints: List[int]) -> bytes:
    """Compress a strictly-increasing list of non-negative ints."""
    _validate(sorted_ints)
    out = bytearray()
    out += _encode_varint(len(sorted_ints))
    if not sorted_ints:
        return bytes(out)
    out += _encode_varint(sorted_ints[0])
    prev = sorted_ints[0]
    for v in sorted_ints[1:]:
        out += _encode_varint(v - prev)
        prev = v
    return bytes(out)


def unpack(data: bytes) -> List[int]:
    """Inverse of :func:`pack`."""
    n, pos = _decode_varint(data, 0)
    if n == 0:
        # Ensure no trailing garbage beyond the count for empty lists.
        return []
    first, pos = _decode_varint(data, pos)
    out = [first]
    append = out.append
    prev = first
    for _ in range(n - 1):
        delta, pos = _decode_varint(data, pos)
        if delta == 0:
            raise InputError("zero delta in stream (duplicate value)")
        prev += delta
        append(prev)
    return out


def unpack_lazy(data: bytes) -> Iterator[int]:
    """Yield values one by one without materializing the full list."""
    n, pos = _decode_varint(data, 0)
    if n == 0:
        return
    first, pos = _decode_varint(data, pos)
    yield first
    prev = first
    for _ in range(n - 1):
        delta, pos = _decode_varint(data, pos)
        if delta == 0:
            raise InputError("zero delta in stream (duplicate value)")
        prev += delta
        yield prev
